<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Models\Expense;use App\Models\ExpenseCategory;use App\Support\BusinessAccess;use Illuminate\Http\Request;
class ExpenseController extends Controller{
 public function categories(Request $r){return response()->json(['data'=>ExpenseCategory::where('business_id',BusinessAccess::id($r))->get()]);}
 public function storeCategory(Request $r){BusinessAccess::requireRole($r,['owner','manager','accountant','super_admin']);$data=$r->validate(['name'=>['required','string','max:100']]);return response()->json(['data'=>ExpenseCategory::create([...$data,'business_id'=>BusinessAccess::id($r)])],201);}
 public function index(Request $r){$q=Expense::with(['category','branch'])->where('business_id',BusinessAccess::id($r));BusinessAccess::scopeBranch($q,$r);return response()->json(['data'=>$q->latest('expense_date')->paginate($r->integer('per_page',20))]);}
 public function store(Request $r){$business=BusinessAccess::id($r);$data=$r->validate(['branch_id'=>['required','integer','exists:branches,id'],'expense_category_id'=>['required','integer','exists:expense_categories,id'],'expense_date'=>['nullable','date'],'amount'=>['required','numeric','gt:0'],'reference'=>['nullable','string','max:100'],'notes'=>['nullable','string']]);BusinessAccess::branch($r,$data['branch_id']);ExpenseCategory::where('business_id',$business)->findOrFail($data['expense_category_id']);$approved=in_array($r->user()->role,['owner','manager','super_admin'],true);$data=[...$data,'business_id'=>$business,'user_id'=>$r->user()->id,'expense_date'=>$data['expense_date']??today(),'approval_status'=>$approved?'approved':'pending','approved_by'=>$approved?$r->user()->id:null];return response()->json(['data'=>Expense::create($data)->load(['category','branch'])],201);}
 public function approve(Request $r,Expense $expense){BusinessAccess::requireRole($r,['owner','manager','super_admin']);abort_unless($expense->business_id===BusinessAccess::id($r),403);BusinessAccess::branch($r,$expense->branch_id);$expense->update(['approval_status'=>'approved','approved_by'=>$r->user()->id]);return response()->json(['data'=>$expense->fresh(['category','branch'])]);}
}
